package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.std.NullifyingDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeIdResolver;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class TypeDeserializerBase__deserializeWithNativeTypeId_TriageGen0Test {

    private TestableTypeDeserializerBase testableBase;
    private JsonParser mockParser;
    private DeserializationContext mockContext;
    private JavaType mockBaseType;
    private TypeIdResolver mockIdResolver;

    /**
     * Concrete subclass to allow testing of protected method and bypass abstract constraints.
     */
    private static class TestableTypeDeserializerBase extends TypeDeserializerBase {
        private JsonDeserializer<Object> mockDeser;
        private JsonDeserializer<Object> mockDefaultDeser;

        protected TestableTypeDeserializerBase(JavaType baseType, TypeIdResolver idRes, String typePropertyName, boolean typeIdVisible, JavaType defaultImpl) {
            super(baseType, idRes, typePropertyName, typeIdVisible, defaultImpl);
        }

        @Override
        public TypeDeserializer forProperty(com.fasterxml.jackson.databind.BeanProperty prop) {
            return null;
        }

        @Override
        public com.fasterxml.jackson.annotation.JsonTypeInfo.As getTypeInclusion() {
            return null;
        }

        @Override
        public String baseTypeName() {
            return "TestBase";
        }

        public void setMockDeserializer(JsonDeserializer<Object> deser) {
            this.mockDeser = deser;
        }

        public void setMockDefaultDeserializer(JsonDeserializer<Object> deser) {
            this.mockDefaultDeser = deser;
        }

        @Override
        protected JsonDeserializer<Object> _findDeserializer(DeserializationContext ctxt, String typeId) throws IOException {
            return mockDeser;
        }

        @Override
        protected JsonDeserializer<Object> _findDefaultImplDeserializer(DeserializationContext ctxt) throws IOException {
            return mockDefaultDeser;
        }

        @Override
        protected Object _deserializeWithNativeTypeId(JsonParser jp, DeserializationContext ctxt) throws IOException {
            return super._deserializeWithNativeTypeId(jp, ctxt);
        }
    }

    @Before
    public void setUp() {
        mockParser = mock(JsonParser.class);
        mockContext = mock(DeserializationContext.class);
        mockBaseType = mock(JavaType.class);
        mockIdResolver = mock(TypeIdResolver.class);
        testableBase = new TestableTypeDeserializerBase(mockBaseType, mockIdResolver, "type", true, null);
    }

    @Test
    public void testDeserializeWithNullTypeId_Success() throws IOException {
        Object expectedResult = new Object();
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);
        when(mockDeser.deserialize(any(), any())).thenReturn(expectedResult);

        testableBase.setMockDefaultDeserializer(mockDeser);

        Object result = testableBase._deserializeWithNativeTypeId(mockParser, mockContext, null);

        assertEquals(expectedResult, result);
        verify(mockDeser).deserialize(mockParser, mockContext);
    }

    @Test
    public void testDeserializeWithNullTypeId_ThrowsMappingException() throws IOException {
        testableBase.setMockDefaultDeserializer(null);

        Object result = testableBase._deserializeWithNativeTypeId(mockParser, mockContext, null);

        assertNull(result);
        verify(mockContext).reportMappingException("No (native) type id found when one was expected for polymorphic type handling");
    }

    @Test
    public void testDeserializeWithStringTypeId_Success() throws IOException {
        String typeId = "myType";
        Object expectedResult = new Object();
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);
        when(mockDeser.deserialize(any(), any())).thenReturn(expectedResult);

        testableBase.setMockDeserializer(mockDeser);

        Object result = testableBase._deserializeWithNativeTypeId(mockParser, mockContext, typeId);

        assertEquals(expectedResult, result);
        verify(mockDeser).deserialize(mockParser, mockContext);
    }

    @Test
    public void testDeserializeWithNonStringTypeId_Success() throws IOException {
        Integer typeIdInt = 123;
        Object expectedResult = new Object();
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);
        when(mockDeser.deserialize(any(), any())).thenReturn(expectedResult);

        testableBase.setMockDeserializer(mockDeser);

        // Should convert Integer to String "123" via String.valueOf
        Object result = testableBase._deserializeWithNativeTypeId(mockParser, mockContext, typeIdInt);

        assertEquals(expectedResult, result);
        // We need to verify _findDeserializer was called with "123". 
        // Since we can't easily verify the internal protected call in the subclass without more spies, 
        // we rely on the fact that the test passes if logic flows correctly.
    }

    @Test(expected = IOException.class)
    public void testDeserialize_ThrowsIOException() throws IOException {
        String typeId = "errorType";
        JsonDeserializer<Object> mockDeser = mock(JsonDeserializer.class);
        when(mockDeser.deserialize(any(), any())).thenThrow(new IOException("IO Error"));

        testableBase.setMockDeserializer(mockDeser);

        testableBase._deserializeWithNativeTypeId(mockParser, mockContext, typeId);
    }
}
